"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Icon } from "@/components/ui/icon"
import { Paper, type PaperProps } from "@/components/ui/paper"
import { diffResult, diffStats, langFromFileName, normaliseLang, parseDiff, tokenizeLines, type DiffLine, type Lang, type Token, type TokenType } from "@/lib/code-highlight"
import { useInk, useMergedRef } from "@/lib/ink/react"
import { makeRng } from "@/lib/ink/rng"
import { codeBodyRecipe, codeRuleRecipe } from "@/lib/ink/recipes/code-block-ink"
import { cn } from "@/lib/utils"

const TOKEN_CLASS: Partial<Record<TokenType, string>> = {
  keyword: "text-(--ll-code-keyword)",
  literal: "text-(--ll-code-literal)",
  number: "text-(--ll-code-number)",
  tag: "text-(--ll-code-tag)",
  function: "text-(--ll-code-function)",
  type: "text-(--ll-code-type)",
  attr: "text-(--ll-code-attr)",
  variable: "text-(--ll-code-variable)",
  string: "text-(--ll-code-string)",
  comment: "text-(--ll-code-comment)",
  punct: "text-(--ll-code-punct)",
}

type Model = {
  code: string
  language: Lang
  diff: boolean
  lines: Array<{ tokens: Token[]; kind: DiffLine["kind"] | "plain"; n: number | null }>
  text: string
  stats: { added: number; removed: number } | null
}

function buildModel(code: string, language: Lang, diff: boolean, startLine: number): Model {
  if (diff) {
    const rows = parseDiff(code)
    const tokens = tokenizeLines(rows.map((r) => r.text).join("\n"), language === "diff" ? "text" : language)
    let n = startLine
    const lines = rows.map((r, i) => ({ tokens: tokens[i] ?? [], kind: r.kind, n: r.kind === "del" || r.kind === "meta" ? null : n++ }))
    return { code, language, diff, lines, text: diffResult(rows), stats: diffStats(rows) }
  }
  const text = code.endsWith("\n") ? code.slice(0, -1) : code
  const tokens = tokenizeLines(text, language)
  return { code, language, diff, lines: tokens.map((t, i) => ({ tokens: t, kind: "plain" as const, n: startLine + i })), text, stats: null }
}

type Ctx = {
  model: Model
  filename?: string
  lineNumbers: boolean
  wrap: boolean
  seed: string
}
const CodeBlockContext = React.createContext<Ctx | null>(null)
function useCode(): Ctx {
  const c = React.useContext(CodeBlockContext)
  if (!c) throw new Error("CodeBlock parts must be used inside <CodeBlock>")
  return c
}

function strikePath(seed: string): { a: string; b: string } {
  const r = makeRng(seed)
  const y = (v: number) => (4 + v + r.gauss(0, 0.35)).toFixed(2)
  return {
    a: `M0 ${y(0.1)} C24 ${y(-0.8)} 44 ${y(0.9)} 66 ${y(-0.2)} S92 ${y(0.6)} 100 ${y(-0.4)}`,
    b: `M2 ${y(1.1)} C30 ${y(0.4)} 58 ${y(1.6)} 98 ${y(0.9)}`,
  }
}
function tickPath(seed: string): string {
  const r = makeRng(seed)
  const j = () => r.gauss(0, 0.5)
  return `M${(1.6 + j()).toFixed(2)} ${(7.4 + j()).toFixed(2)} L${(5.1 + j()).toFixed(2)} ${(11.4 + j()).toFixed(2)} L${(12.6 + j()).toFixed(2)} ${(2.2 + j()).toFixed(2)}`
}

function Strike({ seed }: { seed: string }) {
  const p = strikePath(seed)
  return (
    <svg aria-hidden="true" focusable="false" viewBox="0 0 100 8" preserveAspectRatio="none" className="pointer-events-none absolute inset-x-[-2px] top-1/2 h-2 w-[calc(100%+4px)] -translate-y-1/2 overflow-visible text-red">
      <path d={p.b} fill="none" stroke="currentColor" strokeWidth={1} strokeLinecap="round" opacity={0.5} vectorEffect="non-scaling-stroke" />
      <path d={p.a} fill="none" stroke="currentColor" strokeWidth={1.7} strokeLinecap="round" vectorEffect="non-scaling-stroke" />
    </svg>
  )
}
function Tick({ seed }: { seed: string }) {
  return (
    <svg aria-hidden="true" focusable="false" viewBox="0 0 14 14" className="pointer-events-none absolute start-1.5 top-1/2 size-3.5 -translate-y-1/2 overflow-visible text-green">
      <path d={tickPath(seed)} fill="none" stroke="currentColor" strokeWidth={1.9} strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

async function copyText(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text)
    return true
  } catch {
    try {
      const was = document.activeElement instanceof HTMLElement ? document.activeElement : null
      const ta = document.createElement("textarea")
      ta.value = text
      ta.setAttribute("readonly", "")
      ta.setAttribute("aria-hidden", "true")
      ta.style.position = "fixed"
      ta.style.opacity = "0"
      document.body.append(ta)
      ta.select()
      const ok = document.execCommand("copy")
      ta.remove()
      was?.focus({ preventScroll: true })
      return ok
    } catch {
      return false
    }
  }
}

function selectCodeOf(button: Element): void {
  const code = button.closest('[data-slot="code-block"]')?.querySelector('[data-slot="code-block-code"]')
  const selection = typeof window === "undefined" ? null : window.getSelection?.()
  if (!code || !selection) return
  const range = document.createRange()
  range.selectNodeContents(code)
  selection.removeAllRanges()
  selection.addRange(range)
}

type CodeBlockProps = Omit<PaperProps, "as" | "children"> & {
  code?: string
  language?: string
  filename?: string
  lineNumbers?: boolean
  diff?: boolean
  wrap?: boolean
  startLine?: number
  copyable?: boolean
  tone?: "dark" | "paper"
  children?: React.ReactNode
}

function CodeBlock({
  code = "",
  language,
  filename,
  lineNumbers = false,
  diff,
  wrap = false,
  startLine = 1,
  copyable = true,
  stock = "slip",
  tape = "top",
  tone = "dark",
  seed,
  className,
  children,
  ref,
  ...props
}: CodeBlockProps) {
  const id = React.useId()
  const s = seed === undefined ? id : String(seed)
  const lang: Lang = language ? normaliseLang(language) : filename ? langFromFileName(filename) : "text"
  const isDiff = diff ?? lang === "diff"
  const model = React.useMemo(() => buildModel(code, lang, isDiff, startLine), [code, lang, isDiff, startLine])
  const ctx = React.useMemo<Ctx>(() => ({ model, filename, lineNumbers, wrap, seed: s }), [model, filename, lineNumbers, wrap, s])
  return (
    <CodeBlockContext.Provider value={ctx}>
      <Paper
        as="figure"
        data-slot="code-block"
        data-tone={tone}
        data-language={lang}
        data-diff={isDiff ? "" : undefined}
        stock={stock}
        tape={tape}
        seed={s}
        ref={ref}
        aria-label={filename ?? (lang === "text" ? "Code" : `${lang} code`)}
        className={cn("m-0 flex max-w-full min-w-0 flex-col text-ink", className)}
        {...props}
      >
        {children ?? (
          <>
            <CodeBlockHeader>
              <CodeBlockTitle />
              <CodeBlockStats />
              {copyable ? (
                <CodeBlockActions>
                  <CodeBlockCopy />
                </CodeBlockActions>
              ) : null}
            </CodeBlockHeader>
            <CodeBlockContent />
          </>
        )}
      </Paper>
    </CodeBlockContext.Provider>
  )
}

function CodeBlockHeader({ className, children, ref, ...props }: React.ComponentProps<"div">) {
  const { seed } = useCode()
  const { hostRef, hostProps, node } = useInk({ recipe: codeRuleRecipe, params: {}, kind: "rule", seed: `${seed}|rule`, still: true })
  return (
    <div
      data-slot="code-block-header"
      ref={useMergedRef<HTMLElement>(hostRef, ref as React.Ref<HTMLElement> | undefined) as React.Ref<HTMLDivElement>}
      {...hostProps}
      className={cn("relative isolate flex min-w-0 items-center gap-3 px-4 pt-3.5 pb-2.5 font-type text-[13px] tracking-wide text-ink-muted forced-colors:border-b forced-colors:border-dashed forced-colors:border-[CanvasText] forced-colors:outline-none!", className)}
      {...props}
    >
      {node}
      {children}
    </div>
  )
}

function CodeBlockTitle({ className, children, ...props }: React.ComponentProps<"span">) {
  const { filename, model } = useCode()
  return (
    <span data-slot="code-block-title" className={cn("ll-ink-room min-w-0 flex-1 truncate", className)} {...props}>
      {children ?? filename ?? model.language}
    </span>
  )
}

function CodeBlockStats({ className, ...props }: React.ComponentProps<"span">) {
  const { model } = useCode()
  if (!model.stats) return null
  return (
    <span data-slot="code-block-stats" className={cn("flex shrink-0 gap-2 tabular-nums", className)} {...props}>
      <span className="text-green">
        <span aria-hidden="true">+</span>
        <span className="sr-only">Added </span>
        {model.stats.added}
      </span>
      <span className="text-red">
        <span aria-hidden="true">-</span>
        <span className="sr-only">Removed </span>
        {model.stats.removed}
      </span>
    </span>
  )
}

function CodeBlockActions({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="code-block-actions" className={cn("flex shrink-0 items-center gap-1", className)} {...props} />
}

function CodeBlockCopy({ className, children, onClick, ...props }: React.ComponentProps<typeof Button>) {
  const { model } = useCode()
  const [state, setState] = React.useState<"idle" | "copied" | "failed">("idle")
  const timer = React.useRef<number | undefined>(undefined)
  React.useEffect(() => () => window.clearTimeout(timer.current), [])
  return (
    <>
      <Button
        data-slot="code-block-copy"
        type="button"
        variant="ghost"
        size="xs"
        aria-label="Copy code"
        className={cn("font-type font-normal tracking-wide text-ink-muted", className)}
        onClick={(e) => {
          onClick?.(e)
          if (e.defaultPrevented) return
          const button = e.currentTarget
          void copyText(model.text).then((ok) => {
            if (!ok) selectCodeOf(button)
            setState(ok ? "copied" : "failed")
            window.clearTimeout(timer.current)
            timer.current = window.setTimeout(() => setState("idle"), 1800)
          })
        }}
        {...props}
      >
        {children ?? (
          <>
            <Icon name={state === "copied" ? "check" : "copy"} />
            {state === "copied" ? "copied" : state === "failed" ? "press Ctrl+C" : "copy"}
          </>
        )}
      </Button>
      <span data-slot="code-block-status" role="status" className="sr-only">
        {state === "copied" ? "Copied" : state === "failed" ? "Could not copy" : ""}
      </span>
    </>
  )
}

function CodeBlockContent({
  code,
  language,
  className,
  ref,
  ...props
}: React.ComponentProps<"pre"> & { code?: string; language?: string }) {
  const ctx = useCode()
  const own = React.useMemo(
    () => (code !== undefined ? buildModel(code, language ? normaliseLang(language) : ctx.model.language, ctx.model.diff, 1) : null),
    [code, language, ctx.model.language, ctx.model.diff]
  )
  const model = own ?? ctx.model
  const { hostRef, hostProps, node } = useInk({ recipe: codeBodyRecipe, params: {}, kind: "code", seed: `${ctx.seed}|body`, still: true })
  return (
    <div data-slot="code-block-body" data-ink-focus="within" ref={hostRef} {...hostProps} className="relative isolate min-w-0">
      {node}
      <pre
        data-slot="code-block-pre"
        ref={ref}
        dir="ltr"
        tabIndex={0}
        className={cn(
          "m-0 max-w-full min-w-0 overflow-x-auto px-4 pt-3 pb-4 font-mono text-[13.5px] leading-[1.7] text-ink outline-hidden [scrollbar-width:thin] calm:text-[13px] calm:leading-[1.6]",
          ctx.wrap ? "whitespace-pre-wrap [overflow-wrap:anywhere]" : "whitespace-pre",
          className
        )}
        {...props}
      >
        <code data-slot="code-block-code" className={cn("block", ctx.wrap ? "w-full" : "w-max min-w-full", "[&>[data-slot=code-line]:nth-child(7n+3)]:opacity-[0.94] [&>[data-slot=code-line]:nth-child(11n+6)]:opacity-[0.9]")}>
          {model.lines.map((l, i) => {
            const removed = l.kind === "del"
            const added = l.kind === "add"
            const meta = l.kind === "meta"
            const Row = added ? "ins" : removed ? "del" : "span"
            const body = l.tokens.map((t, k) => (
              <span key={k} className={TOKEN_CLASS[t.type]}>
                {t.text}
              </span>
            ))
            return (
              <Row
                key={i}
                data-slot="code-line"
                data-line={ctx.lineNumbers && l.n !== null ? l.n : undefined}
                data-diff={added ? "add" : removed ? "del" : undefined}
                className={cn(
                  "relative block min-h-lh no-underline",
                  ctx.lineNumbers ? (model.diff ? "ps-14" : "ps-11") : model.diff ? "ps-7" : undefined,
                  ctx.lineNumbers && "before:pointer-events-none before:absolute before:w-8 before:text-end before:text-pencil-text before:tabular-nums before:select-none before:content-[attr(data-line)]",
                  ctx.lineNumbers && (model.diff ? "before:start-5" : "before:start-0"),
                  meta && "text-pencil-text"
                )}
              >
                {model.diff && added ? <Tick seed={`${ctx.seed}|t${i}`} /> : null}
                {model.diff && added ? <span className="sr-only select-none">Added: </span> : null}
                {removed ? <span className="sr-only select-none">Removed: </span> : null}
                {removed ? (
                  <span className="relative inline-block max-w-full text-ink-muted">
                    {body}
                    <Strike seed={`${ctx.seed}|s${i}`} />
                  </span>
                ) : (
                  body
                )}
                {i < model.lines.length - 1 ? "\n" : null}
              </Row>
            )
          })}
        </code>
      </pre>
    </div>
  )
}

export { CodeBlock, CodeBlockHeader, CodeBlockTitle, CodeBlockStats, CodeBlockActions, CodeBlockCopy, CodeBlockContent }
export type { CodeBlockProps }

export type TokenType = "plain" | "comment" | "string" | "keyword" | "literal" | "number" | "function" | "type" | "tag" | "attr" | "variable" | "punct"

export interface Token {
  type: TokenType
  text: string
}

export type Lang = "tsx" | "ts" | "jsx" | "js" | "css" | "bash" | "json" | "diff" | "text"

const ALIASES: Record<string, Lang> = {
  tsx: "tsx",
  ts: "ts",
  typescript: "ts",
  jsx: "jsx",
  js: "js",
  javascript: "js",
  mjs: "js",
  cjs: "js",
  css: "css",
  scss: "css",
  json: "json",
  jsonc: "json",
  bash: "bash",
  sh: "bash",
  shell: "bash",
  zsh: "bash",
  console: "bash",
  diff: "diff",
  patch: "diff",
  html: "text",
  text: "text",
  txt: "text",
}

export function normaliseLang(lang: string | undefined): Lang {
  return ALIASES[(lang ?? "").toLowerCase()] ?? "text"
}

export function langFromFileName(name: string): Lang {
  const dot = name.lastIndexOf(".")
  return dot < 0 ? "text" : normaliseLang(name.slice(dot + 1))
}

const KEYWORDS = new Set(
  (
    "abstract as async await break case catch class const continue debugger declare default delete do else enum export extends " +
    "finally for from function get if implements import in infer instanceof interface is keyof let namespace new of override " +
    "private protected public readonly return satisfies set static super switch this throw try type typeof var void while with yield"
  ).split(" ")
)
const LITERALS = new Set(["true", "false", "null", "undefined", "NaN", "Infinity"])
const BASH_KEYWORDS = new Set("if then else elif fi for while until do done case esac in function select time export local return exit source alias unset".split(" "))

const WS = /^\s+/
const IDENT = /^[A-Za-z_$][\w$]*/
const NUMBER = /^(?:0[xX][\da-fA-F_]+|0[bB][01_]+|\d[\d_]*(?:\.\d[\d_]*)?(?:[eE][+-]?\d+)?n?|\.\d[\d_]*)/
const OPERATOR = /^(?:=>|\.\.\.|\?\?=?|\?\.|[=!<>]=?=?|&&=?|\|\|=?|[+\-*/%&|^~?:]=?|<<=?|>>>?=?)/
const PUNCT = /^[()[\];,.@#\\{}]/

function push(out: Token[], type: TokenType, text: string): void {
  if (!text) return
  const last = out[out.length - 1]
  if (last && last.type === type && (type === "plain" || type === "punct")) last.text += text
  else out.push({ type, text })
}

function stringEnd(src: string, start: number, quote: string): number {
  let i = start + 1
  while (i < src.length) {
    const c = src[i]
    if (c === "\\") i += 2
    else if (c === quote) return i + 1
    else if (c === "\n" && quote !== "`") return i
    else i++
  }
  return src.length
}

function templateEnd(src: string, start: number): number {
  let i = start + 1
  while (i < src.length) {
    const c = src[i]
    if (c === "\\") i += 2
    else if (c === "`") return i + 1
    else if (c === "$" && src[i + 1] === "{") {
      let depth = 1
      i += 2
      while (i < src.length && depth) {
        const d = src[i]
        if (d === "{") depth++
        else if (d === "}") depth--
        else if (d === "`") {
          i = templateEnd(src, i)
          continue
        }
        i++
      }
    } else i++
  }
  return src.length
}

type Mode = "js" | "tag" | "children"

function tokenizeJs(src: string, jsx: boolean): Token[] {
  const out: Token[] = []
  const modes: Array<{ mode: Mode; depth: number; closing?: boolean }> = [{ mode: "js", depth: 0 }]
  let i = 0
  let prev = ""
  const startsExpression = () => prev === "" || /[(=,:?{[&|!]$/.test(prev) || prev === "=>" || prev === "return" || prev === "&&" || prev === "||" || prev === "??"
  while (i < src.length) {
    const top = modes[modes.length - 1]
    const rest = src.slice(i, i + 400)
    let m: RegExpExecArray | null
    if (top.mode === "children") {
      const j = src.slice(i).search(/[<{]/)
      const stop = j < 0 ? src.length : i + j
      if (stop > i) {
        push(out, "plain", src.slice(i, stop))
        i = stop
        continue
      }
      if (src[i] === "{") {
        push(out, "punct", "{")
        modes.push({ mode: "js", depth: 1 })
        prev = "{"
        i++
        continue
      }
      const close = /^<\/([A-Za-z_$][\w$.-]*)?\s*>/.exec(rest)
      if (close) {
        push(out, "punct", "</")
        push(out, "tag", close[1] ?? "")
        push(out, "punct", ">")
        modes.pop()
        prev = ">"
        i += close[0].length
        continue
      }
      const open = /^<([A-Za-z_$][\w$.-]*)?/.exec(rest)
      if (open) {
        push(out, "punct", "<")
        push(out, "tag", open[1] ?? "")
        modes.push({ mode: "tag", depth: 0 })
        i += open[0].length
        continue
      }
      push(out, "plain", "<")
      i++
      continue
    }
    if (top.mode === "tag") {
      if ((m = WS.exec(rest))) {
        push(out, "plain", m[0])
        i += m[0].length
      } else if (rest.startsWith("/>")) {
        push(out, "punct", "/>")
        modes.pop()
        prev = ">"
        i += 2
      } else if (rest[0] === ">") {
        push(out, "punct", ">")
        modes.pop()
        modes.push({ mode: "children", depth: 0 })
        i++
      } else if (rest[0] === '"' || rest[0] === "'") {
        const e = stringEnd(src, i, rest[0])
        push(out, "string", src.slice(i, e))
        i = e
      } else if (rest[0] === "{") {
        push(out, "punct", "{")
        modes.push({ mode: "js", depth: 1 })
        prev = "{"
        i++
      } else if ((m = /^[\w$:.-]+/.exec(rest))) {
        push(out, "attr", m[0])
        i += m[0].length
      } else if (rest.startsWith("=")) {
        push(out, "punct", "=")
        i++
      } else {
        push(out, "plain", rest[0])
        i++
      }
      continue
    }
    if ((m = WS.exec(rest))) {
      push(out, "plain", m[0])
      i += m[0].length
      continue
    }
    if (rest.startsWith("//")) {
      const e = src.indexOf("\n", i)
      const end = e < 0 ? src.length : e
      push(out, "comment", src.slice(i, end))
      i = end
      continue
    }
    if (rest.startsWith("/*")) {
      const e = src.indexOf("*/", i + 2)
      const end = e < 0 ? src.length : e + 2
      push(out, "comment", src.slice(i, end))
      i = end
      continue
    }
    const c = rest[0]
    if (c === '"' || c === "'") {
      const e = stringEnd(src, i, c)
      push(out, "string", src.slice(i, e))
      i = e
      prev = c
      continue
    }
    if (c === "`") {
      const e = templateEnd(src, i)
      push(out, "string", src.slice(i, e))
      i = e
      prev = c
      continue
    }
    if (top.depth > 0 || modes.length > 1) {
      if (c === "{") top.depth++
      else if (c === "}") {
        top.depth--
        if (top.depth === 0 && modes.length > 1) {
          push(out, "punct", "}")
          modes.pop()
          prev = "}"
          i++
          continue
        }
      }
    }
    if (jsx && c === "<" && startsExpression()) {
      const open = /^<([A-Za-z_$][\w$.-]*)?(?=[\s/>])/.exec(rest)
      if (open) {
        push(out, "punct", "<")
        push(out, "tag", open[1] ?? "")
        modes.push({ mode: "tag", depth: 0 })
        i += open[0].length
        continue
      }
    }
    if ((m = NUMBER.exec(rest))) {
      push(out, "number", m[0])
      i += m[0].length
      prev = m[0]
      continue
    }
    if ((m = IDENT.exec(rest))) {
      const w = m[0]
      const after = src.slice(i + w.length, i + w.length + 60)
      let type: TokenType = "plain"
      if (LITERALS.has(w)) type = "literal"
      else if (KEYWORDS.has(w) && prev !== ".") type = "keyword"
      else if (/^\s*(?:<[^>()]*>)?\s*\(/.test(after) && !/^[A-Z]/.test(w)) type = "function"
      else if (/^[A-Z][a-z0-9]/.test(w)) type = "type"
      push(out, type, w)
      i += w.length
      prev = w
      continue
    }
    if ((m = OPERATOR.exec(rest))) {
      push(out, "punct", m[0])
      i += m[0].length
      prev = m[0]
      continue
    }
    if ((m = PUNCT.exec(rest))) {
      push(out, "punct", m[0])
      i++
      prev = m[0]
      continue
    }
    push(out, "plain", c)
    i++
  }
  return out
}

function tokenizeCss(src: string): Token[] {
  const out: Token[] = []
  let i = 0
  let depth = 0
  let inValue = false
  let paren = 0
  while (i < src.length) {
    const rest = src.slice(i, i + 300)
    let m: RegExpExecArray | null
    if ((m = WS.exec(rest))) {
      push(out, "plain", m[0])
      i += m[0].length
    } else if (depth === 0 && rest[0] === "(") {
      paren++
      push(out, "punct", "(")
      i++
    } else if (depth === 0 && rest[0] === ")") {
      paren = Math.max(0, paren - 1)
      push(out, "punct", ")")
      i++
    } else if (depth === 0 && paren > 0 && (m = /^[\w-]+(?=\s*:)/.exec(rest))) {
      push(out, "attr", m[0])
      i += m[0].length
    } else if (depth === 0 && paren > 0 && (m = /^-?\d*\.?\d+(?:[a-z%]+)?/.exec(rest))) {
      push(out, "number", m[0])
      i += m[0].length
    } else if (depth === 0 && paren > 0 && (m = /^[\w-]+/.exec(rest))) {
      push(out, "plain", m[0])
      i += m[0].length
    } else if (rest.startsWith("/*")) {
      const e = src.indexOf("*/", i + 2)
      const end = e < 0 ? src.length : e + 2
      push(out, "comment", src.slice(i, end))
      i = end
    } else if (rest[0] === '"' || rest[0] === "'") {
      const e = stringEnd(src, i, rest[0])
      push(out, "string", src.slice(i, e))
      i = e
    } else if (rest[0] === "{") {
      depth++
      inValue = false
      push(out, "punct", "{")
      i++
    } else if (rest[0] === "}") {
      depth = Math.max(0, depth - 1)
      inValue = false
      push(out, "punct", "}")
      i++
    } else if (rest[0] === ";") {
      inValue = false
      push(out, "punct", ";")
      i++
    } else if ((m = /^@[\w-]+/.exec(rest))) {
      push(out, "keyword", m[0])
      i += m[0].length
    } else if (depth > 0 && !inValue && (m = /^(--[\w-]+|-?[a-zA-Z][\w-]*)(?=\s*:)/.exec(rest))) {
      push(out, "attr", m[0])
      i += m[0].length
    } else if (rest[0] === ":" && depth > 0 && !inValue) {
      inValue = true
      push(out, "punct", ":")
      i++
    } else if (inValue && (m = /^!important/.exec(rest))) {
      push(out, "keyword", m[0])
      i += m[0].length
    } else if (inValue && (m = /^#[\da-fA-F]{3,8}\b/.exec(rest))) {
      push(out, "number", m[0])
      i += m[0].length
    } else if (inValue && (m = /^-?\d*\.?\d+(?:[a-z%]+)?/.exec(rest))) {
      push(out, "number", m[0])
      i += m[0].length
    } else if (inValue && (m = /^([\w-]+)(?=\()/.exec(rest))) {
      push(out, "function", m[0])
      i += m[0].length
    } else if (inValue && (m = /^--[\w-]+/.exec(rest))) {
      push(out, "variable", m[0])
      i += m[0].length
    } else if (!inValue && (m = /^(?:[.#][\w-]+|[a-zA-Z][\w-]*|\*|&)/.exec(rest))) {
      push(out, "tag", m[0])
      i += m[0].length
    } else if ((m = /^[\w-]+/.exec(rest))) {
      push(out, "plain", m[0])
      i += m[0].length
    } else {
      push(out, "punct", rest[0])
      i++
    }
  }
  return out
}

function tokenizeJson(src: string): Token[] {
  const out: Token[] = []
  let i = 0
  while (i < src.length) {
    const rest = src.slice(i, i + 200)
    let m: RegExpExecArray | null
    if ((m = WS.exec(rest))) {
      push(out, "plain", m[0])
      i += m[0].length
    } else if (rest.startsWith("//") || rest.startsWith("/*")) {
      const block = rest.startsWith("/*")
      const e = block ? src.indexOf("*/", i + 2) : src.indexOf("\n", i)
      const end = e < 0 ? src.length : block ? e + 2 : e
      push(out, "comment", src.slice(i, end))
      i = end
    } else if (rest[0] === '"') {
      const e = stringEnd(src, i, '"')
      const isKey = /^\s*:/.test(src.slice(e, e + 40))
      push(out, isKey ? "attr" : "string", src.slice(i, e))
      i = e
    } else if ((m = /^-?\d[\d.eE+-]*/.exec(rest))) {
      push(out, "number", m[0])
      i += m[0].length
    } else if ((m = /^(?:true|false|null)\b/.exec(rest))) {
      push(out, "literal", m[0])
      i += m[0].length
    } else {
      push(out, "punct", rest[0])
      i++
    }
  }
  return out
}

function tokenizeBash(src: string): Token[] {
  const out: Token[] = []
  let i = 0
  let command = true
  while (i < src.length) {
    const rest = src.slice(i, i + 300)
    let m: RegExpExecArray | null
    if (rest[0] === "\n") {
      push(out, "plain", "\n")
      command = true
      i++
    } else if ((m = /^[ \t]+/.exec(rest))) {
      push(out, "plain", m[0])
      i += m[0].length
    } else if (rest[0] === "#" && (i === 0 || /\s/.test(src[i - 1]))) {
      const e = src.indexOf("\n", i)
      const end = e < 0 ? src.length : e
      push(out, "comment", src.slice(i, end))
      i = end
    } else if (command && (m = /^[$>] /.exec(rest)) && (i === 0 || src[i - 1] === "\n")) {
      push(out, "punct", m[0])
      i += m[0].length
    } else if (rest[0] === '"' || rest[0] === "'") {
      const e = stringEnd(src, i, rest[0])
      push(out, "string", src.slice(i, e))
      i = e
      command = false
    } else if ((m = /^\$(?:\{[^}]*\}|[A-Za-z_]\w*|[0-9@#?$!*-])/.exec(rest))) {
      push(out, "variable", m[0])
      i += m[0].length
      command = false
    } else if ((m = /^(?:&&|\|\||[|;&]|>>?|<<?|2>&1)/.exec(rest))) {
      push(out, "punct", m[0])
      i += m[0].length
      command = m[0] !== ">" && m[0] !== ">>" && m[0] !== "<" && m[0] !== "<<"
    } else if (!command && (m = /^--?[A-Za-z][\w-]*(?:=[^\s]*)?/.exec(rest))) {
      push(out, "attr", m[0])
      i += m[0].length
    } else if ((m = /^[^\s|;&<>"'$#]+/.exec(rest))) {
      const w = m[0]
      const type: TokenType = command || BASH_KEYWORDS.has(w) ? "keyword" : /^\d+$/.test(w) ? "number" : "plain"
      push(out, type, w)
      i += w.length
      command = false
    } else {
      push(out, "plain", rest[0])
      i++
    }
  }
  return out
}

export function tokenize(code: string, lang: Lang | string): Token[] {
  const l = normaliseLang(lang)
  switch (l) {
    case "tsx":
    case "jsx":
      return tokenizeJs(code, true)
    case "ts":
    case "js":
      return tokenizeJs(code, false)
    case "css":
      return tokenizeCss(code)
    case "json":
      return tokenizeJson(code)
    case "bash":
      return tokenizeBash(code)
    default:
      return code ? [{ type: "plain", text: code }] : []
  }
}

export function tokenizeLines(code: string, lang: Lang | string): Token[][] {
  const lines: Token[][] = [[]]
  for (const t of tokenize(code, lang)) {
    const parts = t.text.split("\n")
    parts.forEach((p, k) => {
      if (k > 0) lines.push([])
      if (p) lines[lines.length - 1].push({ type: t.type, text: p })
    })
  }
  return lines
}

export type DiffKind = "add" | "del" | "ctx" | "meta"

export interface DiffLine {
  kind: DiffKind
  text: string
}

export function parseDiff(code: string): DiffLine[] {
  const out: DiffLine[] = []
  const lines = code.split("\n")
  if (lines.length && lines[lines.length - 1] === "") lines.pop()
  for (const l of lines) {
    if (/^(?:diff --git |index [\da-f]+\.\.|--- (?:a\/|\/dev\/null)|\+\+\+ (?:b\/|\/dev\/null)|@@ |\\ No newline at end of file)/.test(l)) out.push({ kind: "meta", text: l })
    else if (l.startsWith("+")) out.push({ kind: "add", text: l.slice(1) })
    else if (l.startsWith("-")) out.push({ kind: "del", text: l.slice(1) })
    else if (l.startsWith(" ")) out.push({ kind: "ctx", text: l.slice(1) })
    else out.push({ kind: "ctx", text: l })
  }
  return out
}

export function diffResult(lines: readonly DiffLine[]): string {
  return lines
    .filter((l) => l.kind === "add" || l.kind === "ctx")
    .map((l) => l.text)
    .join("\n")
}

export function diffStats(lines: readonly DiffLine[]): { added: number; removed: number } {
  let added = 0
  let removed = 0
  for (const l of lines) {
    if (l.kind === "add") added++
    else if (l.kind === "del") removed++
  }
  return { added, removed }
}

